{"path": "/app/pipeline_parallel.py", "content": "import inspect
from typing import Iterable, List, Optional, Tuple

import torch
import torch.distributed as dist
import torch.nn.functional as F


def _partition_layers(num_layers: int, world_size: int) -> List[Tuple[int, int]]:
    base = num_layers // world_size
    remainder = num_layers % world_size
    partitions = []
    start = 0
    for rank in range(world_size):
        count = base + (1 if rank < remainder else 0)
        end = start + count
        partitions.append((start, end))
        start = end
    return partitions


def _filter_kwargs(fn, kwargs):
    signature = inspect.signature(fn)
    return {k: v for k, v in kwargs.items() if k in signature.parameters}


def _call_layer(layer, hidden_states, **kwargs):
    filtered = _filter_kwargs(layer.forward, kwargs)
    outputs = layer(hidden_states, **filtered)
    if isinstance(outputs, (tuple, list)):
        return outputs[0]
    return outputs


def _build_position_ids(batch_size: int, seq_len: int, device: torch.device) -> torch.Tensor:
    return torch.arange(seq_len, device=device, dtype=torch.long).unsqueeze(0).expand(batch_size, seq_len)


def _build_causal_attention_mask(batch_size: int, seq_len: int, dtype: torch.dtype, device: torch.device) -> torch.Tensor:
    mask_value = torch.finfo(dtype).min
    causal_mask = torch.full((seq_len, seq_len), mask_value, device=device, dtype=dtype)
    causal_mask = torch.triu(causal_mask, diagonal=1)
    causal_mask = causal_mask.unsqueeze(0).unsqueeze(0)
    if batch_size != 1:
        causal_mask = causal_mask.expand(batch_size, 1, seq_len, seq_len).contiguous()
    return causal_mask


def _get_microbatch_shape(inputs, targets, index: int) -> Tuple[int, int]:
    if inputs is not None and inputs[index] is not None:
        shape = inputs[index].shape
        return int(shape[0]), int(shape[1])
    if targets is not None and targets[index] is not None:
        shape = targets[index].shape
        return int(shape[0]), int(shape[1])
    raise ValueError("Cannot infer microbatch shape.")


def train_step_pipeline_afab(model, inputs, targets, device, dtype):
    if dist.is_initialized():
        rank = dist.get_rank()
        world_size = dist.get_world_size()
    else:
        rank = 0
        world_size = 1

    if device.type == "cuda":
        torch.cuda.set_device(device)

    model.to(device=device, dtype=dtype)
    model.train()

    if inputs is not None:
        num_microbatches = len(inputs)
    elif targets is not None:
        num_microbatches = len(targets)
    else:
        raise ValueError("inputs or targets must be provided")

    layers = model.model.layers
    num_layers = len(layers)
    partitions = _partition_layers(num_layers, world_size)
    start, end = partitions[rank]
    local_layers = layers[start:end]

    last_rank = world_size - 1

    output_hiddens: List[torch.Tensor] = []
    input_hiddens: List[torch.Tensor] = []
    losses: List[torch.Tensor] = []

    hidden_size = getattr(model.config, "hidden_size", None)
    if hidden_size is None:
        hidden_size = model.model.embed_tokens.embedding_dim

    for micro_idx in range(num_microbatches):
        if rank == 0:
            input_ids = inputs[micro_idx].to(device=device)
            hidden_states = model.model.embed_tokens(input_ids)
        else:
            batch_size, seq_len = _get_microbatch_shape(inputs, targets, micro_idx)
            hidden_states = torch.empty(
                (batch_size, seq_len, hidden_size), device=device, dtype=dtype
            )
            dist.recv(hidden_states, src=rank - 1, tag=micro_idx)

        hidden_states = hidden_states.to(device=device, dtype=dtype)

        if rank != 0:
            hidden_states.requires_grad_(True)
            input_hiddens.append(hidden_states)

        batch_size, seq_len = hidden_states.shape[:2]
        position_ids = _build_position_ids(batch_size, seq_len, device)
        attention_mask = _build_causal_attention_mask(batch_size, seq_len, dtype, device)

        for layer in local_layers:
            hidden_states = _call_layer(
                layer,
                hidden_states,
                attention_mask=attention_mask,
                position_ids=position_ids,
                past_key_value=None,
                output_attentions=False,
                use_cache=False,
                cache_position=None,
                position_embeddings=None,
            )

        if rank == last_rank:
            if hasattr(model.model, "norm") and model.model.norm is not None:
                hidden_states = model.model.norm(hidden_states)
            logits = model.lm_head(hidden_states)
            target_ids = targets[micro_idx].to(device=device)
            loss = F.cross_entropy(
                logits.view(-1, logits.size(-1)),
                target_ids.view(-1),
                ignore_index=-100,
            )
            loss = loss / float(num_microbatches)
            losses.append(loss)
        else:
            output_hiddens.append(hidden_states)
            dist.send(hidden_states.detach(), dst=rank + 1, tag=micro_idx)

    backward_tag_base = 1000

    for micro_idx in range(num_microbatches):
        if rank == last_rank:
            losses[micro_idx].backward()
            if world_size > 1:
                grad_input = input_hiddens[micro_idx].grad
                grad_input = grad_input.to(device=device, dtype=dtype)
                dist.send(grad_input, dst=rank - 1, tag=backward_tag_base + micro_idx)
        elif rank > 0:
            grad_output = torch.empty_like(output_hiddens[micro_idx], device=device, dtype=dtype)
            dist.recv(grad_output, src=rank + 1, tag=backward_tag_base + micro_idx)
            output_hiddens[micro_idx].backward(grad_output)
            grad_input = input_hiddens[micro_idx].grad
            grad_input = grad_input.to(device=device, dtype=dtype)
            dist.send(grad_input, dst=rank - 1, tag=backward_tag_base + micro_idx)
        else:
            grad_output = torch.empty_like(output_hiddens[micro_idx], device=device, dtype=dtype)
            dist.recv(grad_output, src=rank + 1, tag=backward_tag_base + micro_idx)
            output_hiddens[micro_idx].backward(grad_output)

    if rank == last_rank:
        return torch.stack(losses).sum()
    return None
